import type { Metadata } from "next";
import { LifeBuoy } from "lucide-react";
import packageJson from "@/package.json";
import { requireArea } from "@/server/authorization/guards";
import { PageHeader } from "@/features/shell/PageHeader";
import { HelpTopics, type HelpTopic } from "@/features/help/HelpTopics";
import { CopyForIt } from "@/features/help/CopyForIt";
import { Hint } from "@/features/ui/Hint";
import Link from "next/link";

// WEB-05 (v1.10.0): a plain, non-confidential browser title.
export const metadata: Metadata = { title: "Help" };

// #13 help page: how-tos, the status words used everywhere (D-017), and
// "Copy details for IT".
// D-249 (owner: "Help includes all the features built new"): every module and
// screen people use, as of v1.40.0.
const TOPICS: HelpTopic[] = [
  { id: "home", group: "Getting around", title: "Home", body: "Approvers open on Approvals – Overview, everyone else on My Work – Overview; Meetings is the third choice. All three work the same way: the period picker beside the switch, a quick-action row with + Add widgets and Customise, four cards (the fourth compares with the period before) and your own widgets for that overview. Approvals: Waiting for me, Overdue for me, My open requests, Decided by me; widgets Waiting for me, Due soon or overdue, Returned to you for changes, My recent requests, Your drafts, Quick insights. My Work: Total, Upcoming, Overdue and Completed, My Tasks, projects with progress, the latest updates and your weekly workload.", link: { href: "/users", label: "Home" } },
  { id: "modules", group: "Getting around", title: "Modules and Coming soon", body: "The main modules are Approvals, Tasks, Projects, Information, Meeting Management and Ticketing (then the AI Assistant), switched on per person as each is released; Home, Inbox, Calendar and Analytics are shared. A module not switched on for you shows as a blurred card or a locked choice marked Coming soon: you can't open it. A page set to Hidden isn't shown at all. With Tasks but not Projects, a task's project shows as its name only, you see only the tasks you are on (and your team's), and project notifications wait until Projects is on. Projects is only given with Tasks." },
  { id: "sidebar", group: "Getting around", title: "The sidebar", body: "Home, Inbox, My Approvals, Tasks, Projects, Information, Meetings, Calendar and Analytics (what your access includes). Groups open and close; ☰ folds the sidebar to icons and the app remembers it. On a tablet-sized window the sidebar starts folded until you open it. On wide screens pages use the room beside the sidebar. On a phone, see On your phone." },
  { id: "request-page", group: "Getting around", title: "The request page and its journey", body: "The Approval Journey card shows the request's status, the road with every level and the van where it is now, the Request Status ring and the detailed levels; refresh checks for news, share copies the link. Below: Request details, Approval levels (who it waits for, progress, time in process), your actions and Attachments, Collaborators and Discussion on the right, then Linked requests, the Timeline (the latest 3, Show more for the rest) and Reuse. Colours: blue in progress, amber on hold, orange changes required, green approved, red rejected, purple withdrawn, grey expired.", link: { href: "/users/requests", label: "My requests" } },
  // v1.59.2 (D-360, D-361): resizable columns, two-line cells, ticket status by department.
  { id: "columns", group: "Getting around", title: "Resize columns and read long text", body: "Drag the right edge of any column title to make that column wider or narrower; double-click the edge for the automatic width. It works in every table and in the task and project lists, and your widths are kept in this browser. Long text in a cell shows two lines, then …: hover to read it all, or widen the column." },
  { id: "ticket-status", group: "Tickets", title: "Ticket status by department", body: "Analytics → Ticket analytics → Status by department: one table for each ticket form (and one for all the forms of a category that has several) for the chosen period, with Total, On time, Delay, Overdue and Not due per department and a Total row. Due is the coordinator's Target date, or the requester's Required date when there is none; a ticket is finished when it is closed (a reopened one counts as open). Pick a Priority on top to see one priority." },
  // v1.59.0 (D-356, D-357): approvers change details from the table; sent-back requests stay on Waiting for me.
  { id: "approver-change", group: "How to", title: "Change a request's details as its approver", body: "On Waiting for me, press Change on a request's row. Change its values (files stay as they are) and, on a custom request, the levels after yours: who approves, add, remove or move a level. A reason is required. New values start your level again so everyone at it sees them; earlier approvals stand unless the new values change the route. The requester and earlier approvers are told what changed and why. Only the approver it waits on now (or their delegate) can change it, not while it is on hold; new approvers must be able to approve and can't be the requester or you." },
  { id: "sent-back", group: "How to", title: "Requests you sent back for changes", body: "My Approvals → Sent back for changes lists every request you sent back, with the requester it waits for, your reason and how long it has been with them (Waiting for me links to it with the count). Open one to review it. When the requester resubmits it, it is back in Waiting for me for your approval. Search, filter, sort any column, group and save views as on the other lists.", link: { href: "/users/queue/sent-back", label: "Sent back for changes" } },
  // v1.58.0 (D-351 to D-353): sorting, saved views, folded groups.
  { id: "sort-views", group: "Getting around", title: "Sort, save views and fold groups", body: "Click any column title to sort A to Z; click again for Z to A (empty values always last; long lists are sorted as a whole, not just one page). Save this view keeps the list as it is now (filters, search, group, sort, tab) under a name; your views are chips above the list: open one, make it your default (it opens when you come to the list with nothing chosen) or delete it. Views are only yours. A request's Priority sorts in every table (the form's first option, e.g. Critical, first; hidden or none last). When you choose a Group by, the groups start folded: click a heading to open it, or use Expand all / Collapse all." },
  { id: "priority", group: "Getting around", title: "Priority and coloured choices", body: "If a request's form has a Priority field (a choice with the key priority), its value shows in colour beside the title, in a Priority column on the request lists (sort or group by it in the order IT set the options) and on Home. Group can also use the requester's Department (on every request list) and any form field; click a group's heading to fold it away. Every list with a table has Group: requests, Waiting for me, tasks, information, meetings, follow-ups and tickets (shown as Form: and the field name); a confidential field you can't see groups as Hidden. IT gives each option of a Dropdown, Radio or Multi-select field a colour in the Form Designer; those values show as coloured pills wherever they appear. Tasks, information, meetings and tickets show their priority the same way, on one scale: Critical, Most Important, Important, High, Normal.", link: { href: "/users/requests", label: "My requests" } },
  { id: "phone", group: "Getting around", title: "On your phone", body: "Below 768 pixels ARS CMS uses its phone layout, laid out like the Asana app (a computer is unchanged). Tabs at the bottom: Home, Approvals, My tasks, Inbox and More. Each list has a big title with … (more pages), and a floating bar: Manage view (Compact mode, sort, group, filters), Choose view (which list) and the red + (new request or task). Tick a task's circle to complete it. On a task: back, Mark complete, copy link and … (its actions); Add a comment stays at the bottom of the screen. Information, New request (one slim row of steps and buttons) and Analytics (filters folded into one row) fit the phone too. Inbox is grouped by day; Choose view has All activity, Bookmarks and Archived. Search (the magnifier) searches requests or tasks and has quick filters. More has your profile, Out of office, Notifications, the other work pages (Information, Meetings, Tickets, Projects, Portfolios: the ones you have), settings, help and Sign out. On a request, Approve, Return, Hold and Reject stay at the bottom. While a page loads you see the shape of that screen. Since v1.89.0 every other list (Tasks, Meetings, Tickets, Admin and Super Admin lists) shows one card per row on a phone, each value after its column name, and every screen has its title at the top (Home too).", link: { href: "/users", label: "Home" } },
  { id: "create", group: "Getting around", title: "Create", body: "The Create button at the top of the sidebar makes anything new: an approval request, a task, a project or a notice (what you're allowed to make)." },
  { id: "search", group: "Getting around", title: "Search everything", body: "Choosing a person anywhere: type a name, code or department; each shows Name - Employee code with the department below. Every search starts from the bar at the top (or Ctrl K): requests, tasks, projects, people, notices, tickets and meetings (those you can see on their lists) and pages. Filters there opens a full search of requests or tasks; Saved searches lists ready-made ones (only those you can open) and your own. Lists have no search boxes of their own: their toolbar has Filter, Sort, Group, Options and a small search icon to narrow what is shown.", link: { href: "/users/search", label: "Full search" } },
  // v1.72.1 (D-395): default views and Clear, the switched-off screen, the way back, "Show more".
  // v1.80.0 (D-407): the interaction, motion and loading review.
  { id: "keyboard-lists", group: "Getting around", title: "Lists with the keyboard; Next waiting for you", body: "On any list, J and K move to the next and previous row (the row lights up) and Enter opens it; the keys do nothing while you type in a field or a comment box, or while a dialog or menu is open. On Waiting for me, A and C still open a request ready to approve or to ask for changes. When you open a request from Waiting for me and decide it, the next request waiting for you opens straight away with a short highlight and \"Your decision is recorded. Next waiting for you\", how many are still waiting, and a link back to the one you decided. Opened from anywhere else (an email, a search), the request stays on screen after your decision with a Next waiting for you → button. Press ? for every shortcut.", link: { href: "/users/queue", label: "Waiting for me" } },
  // v1.87.0 (D-417): navigation continuity and one overlay stack.
  { id: "keep-your-place", group: "Getting around", title: "Closing keeps the list as it was; Esc closes what is on top", body: "Closing a task or record beside a list (×, Esc or a click outside) leaves the list at the same height with its filters and sort, and adds no step to Back, so Back doesn't reopen it. Folded groups stay folded when you come back in the same tab. A record's breadcrumb and ← Back return to the list as you left it, named after the list you came from (Task Summary, Inbox…); a request, task, ticket, meeting or notice opened from Admin → Records offers ← Back to Admin → Records. ← Back on a colleague's card opened from outside ARS CMS goes to Home. Browser Back with an unsent comment beside a list asks Discard draft? first. If you are signed out, Sign in again brings back the same view: the page, the task or record beside it, its filters and sort. Esc and a click outside close only what is on top: a menu, picker or the search over a task closes first. A task in its centred window keeps the keyboard inside it. Esc while a comment is sending waits for it. Reduced motion on your device turns every animation off." },
  { id: "place-and-feedback", group: "Getting around", title: "Back keeps your place; how the app answers", body: "Back from a request returns the list at the same place with the row you opened lit and selected. A click on a sort title, a page number, a tab or a quick filter dims the table until the new one arrives, and the clicked link shows a small spinner; lists show a table-shaped outline while they load. Done things (Saved, Posted, View saved) show as a short message in the corner that repeats what you pressed; problems stay next to the form, with the field's own message under the field. A comment appears at once as \"Posting…\" and goes away again (your words stay in the box) if it can't be sent. Closing Create task or Change details by Escape, × or a click outside after typing asks Discard draft? (Keep editing / Discard). On a phone, swipe a sheet down to close it. Dialogs and menus open and close with a short fade, and a new page fades in with a small rise (Back and Forward stay instant); with Reduce motion on in your device, only a quick fade, nothing moves, and pages don't animate.", link: { href: "/users/requests", label: "My requests" } },
  { id: "finding-your-way", group: "Getting around", title: "Finding your way back", body: "A list you saved a default view for opens with it; Clear or Reset filters on that list shows everything (the default comes back the next time you open the list). A part IT has switched off (Tasks, Information, Analytics, AI Assistant, Portfolios, Project templates) says so on a \"switched off\" page with Go to Home; your data in it is kept. Projects, templates and portfolios show Projects › or Portfolios › above the name; a colleague's card has ← Back. A list that shows only the latest entries says so, with Show more. An old Task home link to a task opens the task." },
  { id: "classic", group: "Getting around", title: "Compact or Classic view", body: "Account menu → View. Compact is this layout. Classic shows Tally-style screens: a gateway of modules with letter keys, Label : value forms, Enter moves to the next field, Ctrl+A accepts, Esc goes back. Text size can be changed in Classic: Account menu → Text size. The menu works with ↓ / ↑, Enter and Esc." },
  { id: "install", group: "Getting around", title: "Install the app", body: "ARS CMS installs like an app and opens in its own window. Android, Chrome or Edge: Install app (on the first visit, or the browser's install icon). iPhone and iPad: Share → Add to Home Screen → Add. Safari on a Mac: File → Add to Dock.", link: { href: "/users/profile/devices", label: "App & devices" } },
  { id: "tour", group: "Getting around", title: "The tour", body: "A short walk through the main screens. Take it again any time from this page or your account menu." },
  { id: "raise", group: "How to", title: "Raise a request", body: "New request has three steps, one page each: Request details, Approval workflow (who approves, in what order; every new level starts as Specific people), then Review & submit, which names every approver. The step bar and the buttons stay at the top while you scroll. Your typing is saved as a draft as you go.", link: { href: "/users/custom", label: "New request" } },
  { id: "approval-templates", group: "How to", title: "Approval templates", body: "Save the approval levels of a request as your own template (on the workflow step, or from a request you raised: Save as an approval template). Approval templates lists them with who approves each level; Use this template starts New request with the same levels, all changeable, and an empty form. Only you see your templates.", link: { href: "/users/new", label: "Approval templates" } },
  { id: "custom", group: "How to", title: "Ask anyone for approval (New request)", body: "New request lets you set your own levels and pick the approvers (Manager and above); your reporting manager is filled in first. Nobody approves their own request. A finished request can be raised again with the same approvers. Fields with a red * are required: Next moves on only when they're filled in, and the approvers can be changed only after Next. A level can be an Approval, a Work task (it also appears in their My Tasks; ticking it there marks it done on the request; untick 'The request waits until it's done' to give it as tasks without holding the request up) or an FYI (they're told and can open the request; put it after the last approval to tell them only on full approval).", link: { href: "/users/custom", label: "New request" } },
  { id: "decide", group: "How to", title: "Approve, reject, ask for changes or put on hold", body: "Open the request from Waiting for me. Approve; Reject (it asks first: it can't be undone); Ask for changes sends it back to the requester; Put on hold pauses it (the response time stops) until it is resumed. After a decision, Next waiting for you opens the next one. You can't act on a request you raised yourself, even when you cover for its approver.", link: { href: "/users/queue", label: "Waiting for me" } },
  { id: "todo", group: "How to", title: "To do (work steps)", body: "Some steps are tasks to do rather than decisions, for example raising a PO. They show a To do badge in Waiting for me; open the request and choose Mark as done." },
  { id: "road", group: "How to", title: "Where my request is (the journey)", body: "On a request, the approval journey at the top shows submitted, one point per level, then the finish flag. The ARS van waits beside the level deciding now, with the request out for review; an approval stamps it green, it goes back into the van and the van drives on; at the flag the road turns green (100%). Red stamp: rejected; orange: changes asked (the van drives back until you resubmit). Work tasks and Information (FYI) are shown beside the road with their own status. Tap a point for who decides there, when and their comments. It checks for news every 10 seconds. Below it, Request details starts with who raised it and their department; your action box, Attachments and Collaborators are on the right." },
  { id: "my-list", group: "How to", title: "My requests: cards, columns and actions", body: "Raised by me / Shared with me, with a card per status (Overdue requests also count under Waiting). Search by number, title, type or the person it waits on; Filter, Sort, Group and Columns (kept on your account). The progress column opens the road; ⋮ has what you can do with that request.", link: { href: "/users/requests", label: "My requests" } },
  { id: "draft", group: "How to", title: "Drafts", body: "A request you started but didn't submit is kept for 30 days. Open it from Home to carry on, or discard it. Submitting removes the draft." },
  { id: "comment-edit", group: "How to", title: "Edit or delete a comment", body: "Under a comment you wrote (on a request, a ticket remark or a task) press Edit, change it and Save, or Delete. IT can do the same on any comment. An edited comment shows (edited); Show edits lists what it said before, with who changed it and when. A deleted one shows This comment was deleted, and Show what it said shows its last text. There is no time limit, and editing doesn't notify anyone again." },
  { id: "format", group: "How to", title: "Formatting comments and adding files", body: "Comment boxes format like an email: the bar below the box has bold, italic, underline, strikethrough, code, link, lists, quote, heading, emoji and @ (or type @ and a name). Files: each chosen file is listed with its name; Add more files adds to the list and × removes one before you send." },
  { id: "task-summary", group: "How to", title: "Task Summary, Assigned to me, Assigned by me", body: "Task Summary lists your incomplete tasks overdue, due today or due in the next 7 days, and the tasks you completed today. Assigned to me is every task given to you, and Assigned by me every task you gave others, with tabs and filters.", link: { href: "/users/work/my-tasks", label: "Task Summary" } },
  // v1.81.0 (D-408): what people notice of a backup restore.
  { id: "restore-notice", group: "Your account", title: "\"Being restored from a backup\" and signed out", body: "When the Super Admin restores ARS from a backup, a notice at the top of every page says so: wait before making changes, because anything saved meanwhile may be lost. When it finishes everyone is signed out; sign in again as usual. Records are then as they were at the backup's time, so check anything you did since and do it again if needed. Backups are kept encrypted; only the Super Admin can make, download or restore them." },
  { id: "google-sign-in", group: "Your account", title: "Google sign-in doesn't let me in", body: "The message says why: no ARS CMS account uses that Google email (choose the Google account of the email IT registered, or ask IT to correct it); the account is linked to another Google sign-in, inactive, or set to User ID and password; or pop-ups are blocked. Give IT the Reference shown under the message." },
  { id: "ooo-tasks", group: "How to", title: "Out of office and your tasks", body: "Setting Out of office moves your open tasks due in those days (from today on; overdue ones keep their dates) to the first working day after you are back; whoever gave them is told. A task given to someone for a day they are away asks first: keep the date, or move it to the day after they return.", link: { href: "/users/delegation", label: "Out of office" } },
  { id: "periodic-own", group: "How to", title: "Repeating tasks for anyone", body: "Since v1.75.0 a periodic (repeating) task can be given to anyone you may give tasks to; several people each get their own repeating copy. The person who set it, the assignee, IT and the project's editors can change or stop the repeat; the next one goes to the same person, who is told. Reassigning a repeating task keeps it repeating. Task Summary's sections are Overdue, Due today, Due in the next 7 days and Completed today." },
  { id: "date-picker", group: "How to", title: "Pick dates and From–To ranges", body: "Every date in Tasks and projects opens one picker: + Start date and Due date at the top (type dd-mm-yyyy or yyyy-mm-dd, or click a day), a Monday-first month with weekly offs and holidays dimmed (point at a holiday for its name), today circled and the range shaded. A start after the due date is swapped. The clock sets the time, repeat opens the repeat settings, Clear empties both, Escape closes. Keys: arrows by day, Page Up / Page Down by month, Home / End to Monday / Sunday, Enter picks. A list's Filters › Due date or Start date also has Is between and Is not between." },
  { id: "task-pane-layout", group: "How to", title: "The task side pane", body: "Click a task anywhere (lists, Board, Calendar, Home, search, the Inbox) and it opens on the right, beside your screen, which stays put. ⤢ opens it in a window in the middle instead (Back to the side pane returns; your choice is kept). ↗ or ⋯ → Open full page opens its own page; Ctrl + click or a middle-click opens that in a new tab. Esc closes it. Mark complete on the left; collaborators with +, Share, like, copy link, ⤢, ↗, ⋯ and close on the right. Then who can see the task (Make public for the project owner of a private project), the name (click to rename), Assignee, Due date (start – due) and Dependencies, Projects with their fields, and the comment box at the bottom. A comment typed but not sent is never lost by accident: Esc, ×, a click outside, a link away or the browser's Back first asks Discard draft? (Keep editing or Discard)." },
  { id: "select-tasks", group: "How to", title: "Select several tasks", body: "In My Tasks or a project's List, Ctrl + click a task (Cmd on a Mac) to select it, Shift + click to select everything from the last one you clicked. Esc clears. The bulk bar changes them together; Select all shown is under the table." },
  { id: "task-remarks", group: "How to", title: "Add a remark with a task action", body: "On a task page, type in Remarks (Actions card), then press Start, Complete, Mark blocked, Cancel or Reassign: the remark goes with the action and is posted to Comments. Planning and people (repeats, tags, followers) folds; click its title to open it." },
  { id: "columns", group: "How to", title: "Arrange a list's columns", body: "On the request lists and Waiting for me, drag a column title onto another to move it (or focus it and press Alt and an arrow key). Columns hides or shows them and has ↑ ↓. Your arrangement is saved for you." },
  { id: "delete-file", group: "How to", title: "Delete a file from a request", body: "The requester, or whoever added the file, can delete it until the first approval. After that files are locked, unless an approver asks for changes. The timeline records the deletion." },
  { id: "mention", group: "How to", title: "Mention someone", body: "In a comment or a task description, type @ and part of their name, then pick them. Only people who can see the record are told; you are shown anyone who wasn't." },
  { id: "pdf", group: "How to", title: "Download a summary", body: "On a request, Download PDF gives the details, levels, decisions and history in one file." },
  { id: "my-tasks", group: "Tasks & projects", title: "My Tasks", body: "Everything given to you, from every project, in your own sections (Overdue, Recently assigned, Today, Upcoming, Later; add your own). Tick to complete; click a name to open it beside the list. List, Board and Calendar views; Filter, Sort and Group. Click a cell in the table to change the due date, assignee, priority, collaborators or tags.", link: { href: "/users/work/my-tasks", label: "My Tasks" } },
  { id: "new-task", group: "Tasks & projects", title: "Give a task (Create task)", body: "Create → Task (or Q in Tasks & projects). Name it; For Myself, or Others (type part of a name); pick a project. In the description type / for the menu, @ to mention, or paste a screenshot to attach it. Task settings: due date, priority, repeat, collaborators. An ad hoc task can go to several people (one copy each). Subtasks: on a task, Add subtask (or the + beside Add a subtask) opens this same window for a subtask under it." },
  { id: "periodic", group: "Tasks & projects", title: "Periodic tasks", body: "A task with a repeat makes its next one when it is completed (daily, weekly on chosen days, monthly, yearly, or a number of days after completion). Periodic tasks lists them with the same tabs, Filter, Sort and Options as Assigned to me (which, like Assigned by me, lists only ad hoc tasks).", link: { href: "/users/work/periodic", label: "Periodic tasks" } },
  { id: "due-time", group: "Tasks & projects", title: "Due date and time", body: "Every task needs a due date. The time is 11:59 pm unless you change it, when creating the task or later when editing it. A due date can be moved but not removed." },
  { id: "formatting", group: "How to", title: "Format text like an email", body: "Descriptions, remarks, comments and other long text have a toolbar with Bold, Italic and Underline; the + button opens lists, quote, heading, link, code, emoji and @mention (or type @ and a name). The text shows formatted wherever it is read." },
  { id: "task-files", group: "Tasks & projects", title: "Add files to a task", body: "Open the task: the Attachments card lists its files, and Add files adds more. You can also paste a file into the description when creating a task." },
  { id: "projects", group: "Tasks & projects", title: "Projects", body: "Group tasks into a project with sections. Views: List, Board, Calendar, Timeline and Overview (status updates). Members and permissions decide who sees and changes what; templates start a new project ready-made.", link: { href: "/users/work/projects", label: "All projects" } },
  // v1.61.0 (D-367): tabs for every view, Save view, the keyboard List, row density, faster refresh.
  { id: "project-tabs", group: "Tasks & projects", title: "Project tabs and saved views", body: "Every view of a project is a tab. Owners and editors: + adds a List, Board, Calendar, Timeline or Overview tab; each tab's ⋯ menu: Rename, Set as default (starred, opens first; greyed on that tab), Make a copy, Copy link, Move left or right, Remove (tasks are never touched; one tab always stays). + Add tab lists the views under Popular and Other. Drag tabs, or focus one and press Alt + ← / →, to reorder. Changing filters, sort, groups or columns shows Unsaved changes: Reset goes back, Save view keeps it for everyone. Everyone else can use the tabs and copy links." },
  { id: "custom-fields", group: "Tasks & projects", title: "Custom fields", body: "Project settings → Fields → Add field (or + after the List's last column): Create new or Choose from library. Types: Text, Number (number, percent, currency, unit; 0–6 decimals), Single- and Multi-select (coloured options; Alt + ↑ / ↓ reorders), Date (with time if you like), People, Formula (+ − × ÷, brackets and functions over the task's number, date and timer fields and its own dates: see Formulas), ID (PREFIX-n for every task, never changed), Timer (start and stop your own; h:mm), Reference (link tasks) and Lookup (a value from the linked task). Tick Add to the ARS field library to reuse a field in other projects (its creator and IT change it), and Notify collaborators to tell followers when the value changes. A column's ▾ menu sorts, filters, groups by, hides or edits the field; Filters, Sort, Groups and the Board's Columns take any field, and Save view keeps them. Remove from project keeps the values; Delete can be restored for 30 days. Owners and editors customise, or only owners when Project permissions → Only admins customise is ticked." },
  // v1.88.0 (D-418): simple formulas (functions, task dates, presets).
  { id: "formulas", group: "Tasks & projects", title: "Formulas", body: "A Formula field works a value out from the task's other fields; nobody types it. Add field → type Formula. Pick a field (or a task date: Start date, Due date, Created on, Completed on, Today) in Select field, press Insert field, and use + − × ÷ and ( ): a date can only be subtracted, and date − date gives days. Fields go in [brackets], for example [Cost] ÷ [Hours]. Functions (any case; open Functions for a help card and Insert): ADD, SUBTRACT, MULTIPLY, DIVIDE; DATEADD(date, days) and DATESUBTRACT(date, days) give a date; ROLLUP(field) adds a number field up over the task's first-level subtasks (add the field again for the task's own value; a subtask has the field once it is also in the project); DAYS(from, to) is to minus from in days; WORKDAYS(from, to) counts working days, both days included, on the Working calendar; IF(condition, then, otherwise) with > < >= <= = <>; ROUND(number, decimals); MIN, MAX, ABS; COALESCE(value, fallback) for empty inputs (otherwise an empty input leaves the result empty). Ready-made: TAT = DAYS([Start date], [Due date]); Delay = DAYS([Start date], [Revised Target]); NFD Delay = DAYS([Today], [NFD]) (negative means overdue); Delay Days = DAYS([Due date], [Completed on]) − 1. Delay and NFD Delay use the project's date field of that name or ask you to pick one. The line under the box says when the formula reads right and whether it gives a number or a date, and Preview shows the result on a task of the project. Formatting opens for a correct formula that gives a number; a date result shows as a date. Limits: 10 inputs, formulas built on formulas at most 2 layers deep, 500 characters, no formula that uses itself. Today is worked out when you look: nothing is written to the task's activity." },
  { id: "dependencies", group: "Tasks & projects", title: "Dependencies and dates that move together", body: "In a task: Blocked by and Blocking list its links with their type. Add dependency: choose Blocked by or Blocking, type part of the other task's name or number (from any project you can see) and pick the type: Finish to start (the usual: it starts once the other is finished), Start to start, Finish to finish or Start to finish. Change the type or remove a link in place; circular links are refused; at most 30 links per task; lag is 0 days for now. Project settings → Dependencies (owners): Off, Keep the gap (waiting tasks move by the same number of days) or Use up the slack (they move only when they would clash). Scheduling: count working days only (weekly offs and holidays skipped). When dates move, you see N dependent tasks moved with Undo (15 minutes). Done tasks never move." },
  { id: "project-layout", group: "Tasks & projects", title: "A project's menus, toolbar and Customize", body: "Every ▾ and ⋯ on a project opens a dropdown menu: ↓ / ↑ move, Home / End jump, a letter jumps to the next item starting with it, Enter chooses, → opens a sub-menu and ← closes it, Escape closes the menu and puts you back on its button. The ▾ beside the project's name: Edit project settings, Manage project permissions, Set colour, Copy project link, Duplicate, Save as template, Add to portfolio, Import ›, Export or sync › (CSV, Excel, time entries, JSON, calendar feed, Print), Archive, Delete project. The members' pictures open Members. Customize opens a panel on the right: + Add (field, form, automation), then Automations, Fields and Forms with their counts, and Project settings. The toolbar: + Add task and its ▾ (Task, Milestone, Section); Filter; Sort (None, Start date, Due date, Assignee, Created by, Created on, Last modified, Completed on, Likes, Alphabetical, your fields, Projects; Ascending / Descending; Clear sort); Group (Group by, or the Board's Columns by; Clear); Options (Show/hide columns, Filters, Sorts, Groups, Subtasks, Rows, each on its own page); and the search icon. A section: + adds a task to it; ⋯ has Add automation to section, Rename section, Add section, expand or collapse subtasks and groups, Hide empty groups and Delete section. Timeline and Gantt: + Add task, ‹ Today ›, the Days / Weeks / Months / Quarters dropdown, zoom − / + and Filter (Incomplete, Completed or All tasks; Just my tasks). Project settings lists its sections beside them (Jump to on a phone). While a project loads, a grey outline of it shows.", link: { href: "/users/work/projects", label: "Projects" } },
  // v1.73.0 (D-396): the other PM screens' menus.
  { id: "pm-menus", group: "Tasks & projects", title: "Menus on Home, Task Summary, portfolios, forms and automations", body: "The same dropdown menus (same keys) as on a project. Owners rename a project by clicking its name in the header (Enter saves, Escape keeps the old name). A task's ⋯: Create follow-up task and Duplicate task open the Create task window filled in; check it and create it. Create task ▾: Create and add another keeps the window open. Task Summary: the ▾ beside the title (Add task, Morning summary email, Table with filters, Calendar feed, Print); each task's ⋯ (open, copy link, go to its project). Home: + Add widgets and Customise at the right end of the quick-action row; each widget's ⋯ (move up or down, half or full width, remove). Portfolios: cards with a New portfolio tile, or View as list; a card's ⋯ (open, copy link, star, join). In a portfolio: the ▾ beside its name, the people pictures open Share, Add work ▾, Filter, Sort and Group menus, a sort menu on each column and a ⋯ on each row (Remove from this portfolio). Form builder: a bar with who may submit (Change), View form, Share form, Copy link and ⋯ (Duplicate form, Unpublish, Delete form). Dashboard: a widget's ⋯ (View chart, Edit chart, Duplicate, Size ›, moves, Remove). Workload: Add task, ‹ Today ›, the Days / Weeks and measure dropdowns. Automations: Choose trigger, Add step and Do this are dropdown menus. Calendar: Filter and Search this view. Sidebar: a section's ⋯ sorts it (A–Z, Recently opened, Manual); the department's + starts a new project or portfolio.", link: { href: "/users/work/portfolios", label: "Portfolios" } },
  { id: "timeline-gantt", group: "Tasks & projects", title: "Timeline and Gantt", body: "The Timeline tab, and a Gantt tab (+ Add tab → Gantt) with Name, Due date and Blocked by columns. The unit dropdown: Days, Weeks, Months or Quarters; zoom in and out; ‹ Today › (previous and next period); Filter (Incomplete, Completed or All tasks; Just my tasks); Sort (Start date, Due date, Alphabetical); Group (Sections or None); Options (Expand or Collapse all sections, Go to today). Drag a bar to move it, its ends to change the start or due date, and its dot onto another bar to link them. Keyboard: Tab to a bar; ← / → move it; Shift + ← / → the due date; Alt + Shift + ← / → the start date; Enter saves; Escape cancels; L links; ↑ / ↓ next bar. Arrows: grey waiting, green done, red when the dates clash. Weekly offs and holidays are shaded; milestones are diamonds. The Project dates bar at the top runs From to To with the project's working days and hours." },
  { id: "critical-path", group: "Tasks & projects", title: "Critical path and slack (Gantt)", body: "On a Gantt tab, Options › Show critical path marks the tasks that decide when the project ends: their bars are striped in amber, the arrows between them thicker, and a box above the chart says how many tasks and working days the path has and when it ends, with the critical tasks in order. Options › Show slack adds a Slack column and a thin bar after each bar: how many working days a task can slip without moving the end (0 = critical). Tab to a bar to hear its slack. It is worked out in working days (weekly offs and holidays skipped); a task waiting for another (Finish to start) begins the next working day; nothing starts before its planned start; completed tasks keep their dates; when the project's To date is earlier than the end, tasks past it show as late. Links from tasks in other projects are not followed. It updates while you drag a bar and after saving; both choices are remembered on this device." },
  { id: "from-to", group: "Tasks & projects", title: "From and To dates and estimated time", body: "A project's start and due dates are its From and To dates. With both set, the project shows its working days (both days counted; weekly offs and holidays skipped) and estimated hours (working days × hours per working day, 8 unless IT changes it in Admin → Set-up → Task settings → Project planning): in the header, on Overview, in Settings, in a portfolio's Duration column and on the Timeline and Gantt. To can't be before From. A task without an estimate is estimated from its dates the same way (only a due date = 1 day), marked \"Estimated from dates\" in its Time section; an estimate you type wins, and emptying it goes back to the dates. Project time totals and Workload's Estimated time add these up.", link: { href: "/users/work/projects", label: "Projects" } },
  { id: "project-dashboard", group: "Tasks & projects", title: "Project dashboard and charts", body: "+ Add tab → Dashboard. A new dashboard has 8 widgets. Owners and editors: Add widget → Chart (Bar, Stacked bar, Grouped bar, Line, Burnup, Burndown, Donut, Number, Lollipop; data from tasks or time entries; X-axis, Y-axis and Add metric on the same axis; filters; data labels; benchmark line) or Text. Hover a column or slice, or Tab to a chart and use ← / →, to read each value; the table icon shows the figures as a table. Reorder: drag a widget's handle, or Tab to it, Space, arrow keys, Space (Escape cancels). Figures count only tasks you can see." },
  { id: "project-automations", group: "Tasks & projects", title: "Project automations (rules)", body: "Project settings → Automations → Add automation (owners and editors; only owners when Only admins customise is ticked). Choose what starts it (a task added, moved to a section, a field or the assignee changed, completed or reopened, due soon or overdue, a file, comment or collaborator added, a form submitted, by hand from a task's ⋯ menu, on a schedule, or a web request), then Add step: move, add to another project, complete or reopen, assign, set the due date (days or working days), priority or a custom field, create a task or subtasks, add a comment, add collaborators or notify people. Add paths for if / otherwise: the first path whose conditions match runs. Every card moves with ↑ / ↓ and is removed with its bin; nothing needs dragging. Save draft keeps your changes; Publish makes them run (Publish stays off until every card is set up). The rule acts with its owner's rights, recorded as ARS-CMS Automation; Become owner takes it over, and so does saving or publishing someone else's rule (they are told). The Run log shows its last 200 runs. Loops are stopped: a rule's own changes never start it again, and at most 3 rules run in a chain." },
  // v1.71.0 (D-384): Files, Messages and Page tabs, time tracking.
  { id: "project-collab", group: "Tasks & projects", title: "Files, Messages, the project page and time", body: "Once IT switches on Projects E, + Add tab in a project offers three more tabs. Files: every file on the project's tasks and subtasks, its form submissions and its messages, as a Gallery or a List; filter by type, task, who added it and date, search, sort; Preview images, Open PDFs, Download anything, Go to task. You only see files on tasks you can see. Messages: Send a message to the project (a subject, formatted text, @mentions, up to 10 files); everyone on the project is told, a Reply tells the people in that conversation, and people you mention are always told if they can see the project. React with an emoji; the writer and IT can Edit or Delete, and Show edits shows the earlier text. Viewers read only. Page: the project's brief. Owners and editors choose Edit (start a line with # for a heading, @ to mention someone, Link a task to add one of the project's tasks); linked tasks show beside it. Version history keeps the newest 50 saves: Show or Restore any of them. If someone saved while you were editing, your save is refused: copy your text, reload and add it again. Time: every task has a Time section: Log time (the day, how long like 1h 30m, 45m or 1:30, a note) or Start timer and Stop; set an Estimate if you plan the task. You change your own entries; the project's owners and editors can change anyone's. The project's Overview shows the time logged against the estimates and Download time entries (CSV); Dashboard time charts and Workload → Estimated time use it too.", link: { href: "/users/work/projects", label: "Projects" } },
  // v1.70.0 (D-383): templates, duplicate, import/export, calendar feeds.
  { id: "templates", group: "Tasks & projects", title: "Templates, copies, import and calendar feeds", body: "Once IT switches on Projects E: a project's ⋯ → Save as template keeps its sections, tasks and subtasks (dates as days from the start; every task keeps a due date), custom fields with their values, dependencies, tabs, dashboard, forms and automations. Projects → Project templates lists your templates, organisation templates (chosen by IT) and those shared with you: Preview, Use template, Rename, Delete. When you use one, give each person in it (a placeholder) to someone, or leave it empty to take those tasks yourself; forms come as unpublished drafts and automations as drafts owned by you. Project settings → Duplicate it: tick what to copy (tasks, subtasks, assignees, due dates, fields, dependencies, tabs, dashboard, forms, automations, members; status updates only if ticked) and move every date by a number of days. Import and export: download the List as CSV or Excel (or the full structure as JSON, owners and editors); import tasks from an Excel or CSV file: read the file, say what each column is, check the rows (each problem is listed by row), then import (rows with problems are left out only if you tick it). Calendar feed (My Tasks and project settings): make a secret address for Google Calendar or Outlook; it shows the open tasks you can see, read-only. Keep it private; make a new one or stop it at any time.", link: { href: "/users/work/templates", label: "Project templates" } },
  // v1.69.0 (D-382): portfolios.
  { id: "portfolios", group: "Tasks & projects", title: "Portfolios", body: "A portfolio groups projects (and other portfolios, up to 5 levels) so you can follow them together, once IT switches it on. + Create → Portfolio (or Projects → Portfolios → Create portfolio): name, colour, who can see it, the tab it opens on, then the projects you can see and the people with a role (owner, editor, commenter or viewer). List: each project's latest status, task progress (completed of all tasks, as a bar and in words), due date, owner, priority and the portfolio's own columns (Customize: text, number, single-select, date or person); filter, sort, group and search; owners and editors Add work (type a name, ↑ / ↓, Enter) and remove rows (the project itself is never changed). Progress: how many are on track, at risk or off track, the portfolio's status updates (owners and editors post them) and About. Timeline: bars by quarter; ↑ / ↓ move between rows and ← / → change the quarters. Dashboard: totals, projects by status, incomplete tasks by project and completion over time. Being in a portfolio never opens its projects: a project you can't see shows as Private project, with who added it, and is left out of every figure. You're told when you're added, when a status update is posted, and (owners) when a project in it goes off track. Deleted portfolios stay 30 days in Deleted.", link: { href: "/users/work/portfolios", label: "Portfolios" } },
  { id: "workload", group: "Tasks & projects", title: "Workload and capacity", body: "+ Add tab → Workload shows each person's open tasks per day or week (or an effort field: a number field, or a timer field in hours) against their capacity a working day (5 tasks or 8 hours unless set). Owners and editors use Set capacity. Weekly offs and holidays have no capacity. Over capacity shows a warning sign and the word Over. Click a cell to see its tasks and reassign them." },
  { id: "calendar-weeks", group: "Tasks & projects", title: "Project calendar: weeks and moving tasks", body: "Weeks or Months at the top right. In Weeks, Saturday and Sunday share a column and a task with a start date shows on every day up to its due day. Drag a task to another day, or focus it, press Space, then ← / → (a day) or ↑ / ↓ (a week) and Enter (Escape cancels). The due time stays and the start date moves with it. No start date lists tasks with only a due date, with a box to set a start date." },
  { id: "status-updates", group: "Tasks & projects", title: "Status updates", body: "In the project's Overview: Headline, Status (required), Owner, Start and Due, Summary and Next steps, Highlights (milestones and tasks completed in the last 7, 14 or 30 days: tick what goes in) and Recipients (the members are told; add anyone else). Remind the project owner every Friday sends a reminder each Friday morning. Owners and editors post; only the author deletes an update." },
  { id: "project-forms", group: "Tasks & projects", title: "Project forms", body: "A form people fill in becomes a task in your project (once IT switches phase C on). Project settings → Forms → Add form (owners and editors; only owners when Only admins customise is ticked). Questions: Text, Long text, Single-select, Multi-select, Date, Number, Attachment and Heading, each with Required, a description and options; move them with ↑ / ↓, by dragging or Alt + ↑ / ↓. Connect to field fills the task's name, description, due date or priority, or a project field of the same type. Add branch on an option shows the questions you tick only when it is chosen. Settings: the section, the task name, the default assignee and the due date in working days (both required), the confirmation, who may submit (everyone signed in, some departments or the members). Publish (off while anything needs fixing) makes a new version; Share copies the link or shows a QR code; people sign in to open it. Each submission is a task at the top of the section, made by ARS-CMS Automation for the person who filled it in, with the answers in its description; they get a confirmation and View request. Home → Forms lists forms you may submit.", link: { href: "/users/work/projects", label: "Projects" } },
  { id: "board-keys", group: "Tasks & projects", title: "Move Board cards with the keyboard", body: "On a project's Board, Tab to a card and press Space to pick it up. ↑ / ↓ move it between cards, ← / → between columns; Space or Enter drops it, Escape puts it back. Each step is read out. Without picking up, the arrow keys move between cards and Enter opens one. Alt + ↑ / ↓ still move a card at once. Moving is off while a sort, filter or search is on. Cards show the project's field values; columns show how many tasks they hold." },
  { id: "task-pane", group: "Tasks & projects", title: "The task pane, reactions, celebrations and Undo", body: "On a wide screen a task opens on the right, beside the screen you are on (any screen since v1.83.0). Drag its left edge (or focus it and press ← / →) to change its width; it is kept for you. Its bar: Mark complete, Collaborators, Like, Copy link, Open full page and ⋯ (Add to another project, Add subtask, Add tags, Attach files, Copy task link, Open full page, Print, Delete task). All activity has an Oldest first / Newest first dropdown. The grey line says who can see the task. Under a comment, the smiley adds a reaction (👍 ❤️ 🎉 😄 👀 ✅); press it again to take it back. Completing or deleting a task shows Undo. Profile → Celebrations: Off, Occasional or Always (never with reduced motion)." },
  { id: "starred-projects", group: "Tasks & projects", title: "Starred and department projects; Deleted", body: "Star a project (☆ in its header or the project list) to see it under Starred in the sidebar; your department's projects are listed too. Each list's ⇅ sorts it Manual, A–Z or Recently opened; in Manual, focus a project and press Alt + ↑ / ↓ to move it. Deleted tasks and projects can be restored for 30 days; after that they are removed for good (Deleted shows the date)." },
  // v1.63.0 (D-369): Home widgets and My Tasks tabs.
  { id: "overview-widgets", group: "Getting around", title: "Widgets on every overview", body: "Approvals, My Work and Meetings each keep your own widgets, separately. + Add widgets (right end of the quick-action row) lists the widgets not shown; each widget's ⋯ moves it up or down, makes it half or full width, or removes it; Customise shows drag handles (keyboard: focus the handle, Space, ↑ / ↓, Space; Escape cancels; Alt + ↑ / ↓ moves at once) and Reset, which puts only that overview back to its default (the screen as it was). On every overview you can add a Private notepad (one note, the same on all three), a day-by-day chart for the period, Needs attention and Quick insights. Lists show only what you may see; meeting figures need the Meetings: dashboard figures access. Moving between the overviews keeps + Add widgets and Customise; Customise ends with the overview you started it on; the period picker shows the period in the address.", link: { href: "/users?home=approvals", label: "Home" } },
  { id: "home-widgets", group: "Tasks & projects", title: "Your Home: widgets and the private notepad", body: "Home → Task Management greets you with today's date and shows your widgets: My Tasks, Projects (Recent or Starred), Latest status updates, Private notepad, My weekly workload, Tasks I've assigned and People (who you report to and your team). Customise shows each widget's controls: drag its handle, or focus the handle and press Space, ↑ / ↓, then Space again (Escape cancels; Alt + ↑ / ↓ moves at once); Half or Full width; Remove; Add widget brings one back; Reset returns to the default. The notepad saves by itself and only you see it. Your layout is kept for you on every device. People who have Tasks but not Approvals get the same Home, with their other modules below it.", link: { href: "/users?home=tasks", label: "Home" } },
  { id: "task-summary-r1", group: "Tasks & projects", title: "Task Summary: range per tab, My sections and rules, CSV", body: "Each Task Summary tab has Show ▾: Summary window (overdue, due today, the next 7 days and completed today, the default) or All my open tasks (everything given to you, with Due later). Your tabs save themselves (Reset goes back to the start), and two tabs may have the same name. Group a List tab by My sections (Group ▾) to use your own sections: Recently assigned (new and reassigned work lands there and stays until you move it), Today, Upcoming, Later and any you add (Add task ▾ › Section). Drag a task, or press Alt + ↑ / ↓ (Alt + Shift to change section); clear the sort and filters first. In a task you own, Task Summary section moves it. Customise › Rules: every night at midnight, tasks due today move to Today and tasks due within N working days to Upcoming (once per due date; holidays don't count); the task's activity says so, only to you. A Board tab's Columns ▾ can be My sections too. Deleting a section moves its tasks to Recently assigned. The chips read Filters: 1, Sorts: 1 and Groups: 1, each with × to clear. Task visibility shows who can see a task from its projects (Everyone at ARS, a department, a project's members, or Collaborators). Title ▾ › Sync / export › CSV downloads the tab's tasks (5 an hour). Only you see your sections and rules.", link: { href: "/users/work/my-tasks", label: "Task Summary" } },
  { id: "task-summary-r2", group: "Tasks & projects", title: "Task Summary: share it, open your team's, Customise › Fields, Board and Calendar settings", body: "Share (lock) beside the title: add people who may open your Task Summary, read-only (Invite works once you choose someone); the list shows who can see it: you, the managers above you (always, read-only) and the people you added, each with Remove. They are told when you add them. Anyone opening someone else's Task Summary sees only the tasks they may already see; the others are left out. The people button next to Share opens a Task Summary shared with you or one of your team's (managers, every level); a banner says Viewing: <name>'s Task Summary · read-only, with Back to my Task Summary. A colleague's profile has View Task Summary when you may open it. Your picture opens your profile. Customise › Fields: the columns your lists show (tick Also use in my List tabs to change the tabs you have). A Board tab has its own Filter (Show all, incomplete or completed; due this or next week), Sort, Group (columns by date or My sections) and Search; a Calendar tab keeps Filter, Options › Show weekends and Weeks or Months. Both save themselves.", link: { href: "/users/work/my-tasks", label: "Task Summary" } },
  { id: "task-summary-r3", group: "Tasks & projects", title: "Task Summary: Dashboard, Notes and Files tabs, Request access, the Tasks card on a profile", body: "+ beside the tabs adds a Dashboard (your open, overdue and due-today numbers, charts by due date, project and priority, and what you completed in the last 14, 30 or 90 days), Files (every file on the tasks given to you) or Notes (your own notes in rich text, saved a second after you stop typing; only you can read them, even when you share your Task Summary). Anyone opening your Task Summary sees your Dashboard and Files tabs counting only the tasks they may already see, and never your notes. If you can't open someone's Task Summary, Request access (with an optional note) tells them; they see the request in Share, with Grant (a read-only share, as Invite) or Decline. A person's profile shows a Tasks card with their soonest open tasks and View all tasks when you may open their Task Summary (your own profile shows My tasks). The Create task window keeps what you typed if the page reloads (in this browser tab only) until you create the task or close it. Grouped by a person, a heading shows their employee code (Name · code); Task Summary's Sort has no Assignee (it is always you)." },
  { id: "my-tasks-tabs", group: "Tasks & projects", title: "Task Summary tabs and Recently assigned", body: "Task Summary has your own tabs, like a project: + adds a List, Board or Calendar tab; each tab's ⋯ menu renames it, sets it as the default, duplicates it, copies its link, moves it or removes it (one always stays). Alt + ← / → on a focused tab reorders. In a List tab, filters, sort and groups show Unsaved changes until you press Save view (Reset goes back). Tasks someone gave you in the last 3 days are under Recently assigned, after Overdue. Only you see your tabs.", link: { href: "/users/work/my-tasks", label: "Task Summary" } },
  { id: "list-keys", group: "Tasks & projects", title: "The List with the keyboard, subtasks and row height", body: "Tab into a project's List: ↑ / ↓ move between rows, → / ← open or close a section or a task's subtasks, Home / End jump to the first or last row, Enter opens the task, Space selects it. ▸ beside a task shows its subtasks; a section's ⋯ menu hides empty groups and expands or collapses all subtasks. Options → Rows picks Comfortable or Compact for your lists. Open lists and tasks refresh every 15 seconds while you look at them, when you come back, and after each change." },
  { id: "task-form", group: "Tasks & projects", title: "Tasks with a form", body: "New task (and Add task) always opens the Create task window. Some task types IT set up have their own form; IT shares the link to such a form, and it opens that type's form directly.", link: { href: "/users/tasks/new", label: "Task with a type" } },
  // v1.51.0 (D-300): Meeting Management.
  { id: "tickets", group: "Tickets", title: "Raise a ticket and what happens next", body: "Tickets (the Ticketing module, given by IT in Users & roles) → Raise a ticket: choose the ticket type, then write the subject and the Issue Description, choose the priority (Critical, Most Important, Important, High, Normal) and the required date (all required), and attach up to 10 files (your name, ID, department and email are filled in). The form's coordinators assign it to an employee with a target date; the employee updates the ticket itself (Start work, then Mark resolved; no task is made). When it's done you're asked to confirm (optionally rate it 1 to 5) or reopen it with a reason (it goes back to the same assignee). Without an answer you're reminded after 2 and 3 working days, and it closes by itself after 4 working days. On My tickets → Assigned to me, the Update column has Start work and Mark resolved for each ticket.", link: { href: "/users/tickets", label: "My tickets" } },
  // v1.56.0 (D-332): the coordinator board.
  // v1.56.0 (D-334): Ticket analytics by access.
  { id: "ticket-analytics", group: "Tickets", title: "Ticket analytics", body: "Analytics → Ticket analytics. The scope at the top decides which tickets count: Whole organisation (IT) is every ticket; otherwise the tickets raised by or assigned to you, your team or your departments, plus every ticket of the forms you coordinate. It shows tickets raised, closed, auto closed, reopened and overdue, response and resolution times, ratings, where the open tickets are and who has them, by category, form, department and priority, and twelve months.", link: { href: "/users/analytics?board=tickets", label: "Ticket analytics" } },
  // v1.57.0 (D-335): item lists ticked as provided.
  { id: "item-list", group: "Tickets", title: "Item lists: items to provide", body: "Some approval and ticket forms have an Item list (for example stationery): add each item and the quantity needed. On the request or ticket, Items to provide shows each item with a Provided tick and how many are provided so far. The request's approvers, the ticket's coordinators and assignee, and IT tick each item when it is handed over (who and when are shown; a tick can be undone). The requester sees the ticks." },
  { id: "ticket-board", group: "Tickets", title: "Coordinator board: where each ticket is now", body: "Tickets → Coordinator board (for coordinators of ticket forms, and IT). A table grouped by status: New (to assign), Reopened, Assigned, In progress, Awaiting confirmation and Closed (last 7 days); the chips above it show each status's count and filter to it. Each row shows who has the ticket, how long it has been in that status, the target date (red when overdue), the needed-by date and when it auto-closes. Filter by category or search, or tick Only overdue. Click a ticket to open it.", link: { href: "/users/tickets/board", label: "Coordinator board" } },
  { id: "ticket-work", group: "Tickets", title: "Tickets for coordinators and assignees", body: "Coordinators: open a new ticket, choose the employee, a target date and remarks, then Assign (no task is made: the assignee updates the ticket); reassign the same way. Ticket dashboards show each category's totals and tickets, with filters. Assignees: on the ticket (or its row in My tickets → Assigned to me) press Start work, add remarks and documents, then Mark resolved with what was done. Resolving asks the requester to confirm; it doesn't close the ticket. Remarks marked Internal, and the files attached to them, aren't shown to the requester.", link: { href: "/users/tickets/dashboards", label: "Ticket dashboards" } },
  { id: "meetings", group: "Meetings", title: "Meetings: who does what", body: "Each meeting has one Meeting Owner and one Coordinator (they can be the same person). The Coordinator schedules it, adds the meeting points, marks attendance and writes the MOM. Only the Meeting Owner approves the points and the MOM. Everything approved is shared with the participants. People are always chosen by typing a name.", link: { href: "/users/meetings", label: "Meetings" } },
  { id: "meeting-schedule", group: "Meetings", title: "Schedule a meeting", body: "Meetings → Schedule a meeting. Required fields have a red *. The date and time start at today and now (change them as you need); the end is always after the start. Choose the type, the Meeting Owner, the Coordinator, participants, and departments (type a department name). An online meeting's link shows on the meeting, in the meetings list and on your Calendar. Everyone on it is told with the date, time, place, link and their role. Optional deadlines: Points due by and MOM due by (the Coordinator is reminded). The Owner decides what happens if the points aren't approved in time: hold the meeting anyway, or don't start until approved.", link: { href: "/users/meetings/new", label: "Schedule a meeting" } },
  { id: "meeting-mom", group: "Meetings", title: "Write the MOM", body: "A meeting can be scheduled before or after it happens; its times can be changed until the MOM goes to the Owner. The Coordinator presses Enter MOM, then ticks: Started on time (if not, enters when it started), Meeting was extended (enters when it ended; the extra minutes are worked out and shown in the details), Points shared in time and MOM in time; ticks attendance (ticked = present), notes the discussion point by point, the decisions, the action items (each with one responsible person, priority and due date) and open points, then sends the MOM to the Meeting Owner. When the Owner approves, each action item becomes a task for its owner, linked to the meeting." },
  { id: "meeting-analytics", group: "Meetings", title: "Meeting analytics", body: "Analytics → Meeting analytics: meetings held, on time (the Coordinator's ticks), attendance, approval times and action follow-up, compared with the previous period, by type, department and Coordinator, action owners, twelve months and what needs attention. Whose meetings follow the scope at the top: yours, your team (everyone below you), the departments you head, or the whole organisation (IT). ED and MD can switch to all meetings.", link: { href: "/users/analytics?board=meetings", label: "Meeting analytics" } },
  { id: "meeting-follow", group: "Meetings", title: "Follow-ups", body: "Follow-ups lists every action item and open point from approved MOMs. When the responsible person completes the task, the Meeting Owner or Coordinator confirms it, or sends it back with a note (the task reopens). Schedule follow-up meeting carries every open action (the same task) and open point into the next meeting. A meeting closes when all its actions are confirmed or carried forward.", link: { href: "/users/meetings/follow-ups", label: "Follow-ups" } },
  { id: "meeting-dashboard", group: "Meetings", title: "Meetings – Overview (Home → Meetings)", body: "Home has a Meetings choice beside Approvals and Task Management: cards (upcoming, to approve, MOM to write, meetings you ran or attended in the period with the change against the period before), your widgets (move, resize, remove, add: also My meeting activity and the private notepad), Needs attention (points or MOM late or due soon, meetings not started or still running, overdue actions, actions to confirm), what's coming up, insights and, for a period: meetings held, points and MOM in time, started on time, attendance and actions done or overdue, by type and department, worked out from the times recorded. You see the meetings you are on; heads of department see their departments'; ED, MD and IT see all.", link: { href: "/users?home=meetings", label: "Meeting Overview" } },
  { id: "inbox", group: "Inbox, information and calendar", title: "Inbox", body: "Every message ARS sends you: approvals, tasks, meetings, information and system messages; the Meetings view has invitations, points and MOM to approve or ready to read, cancellations, deadline reminders and action follow-ups. Open one to go to it; Bookmark what you'll come back to and Archive what's done. Mark all as read can be undone.", link: { href: "/users/inbox", label: "Inbox" } },
  { id: "information", group: "Inbox, information and calendar", title: "Information (notices)", body: "Circulars and notices for you are in the Information inbox; press Acknowledge when a notice asks. With permission, New information sends one to people, departments or everyone.", link: { href: "/users/information", label: "Information inbox" } },
  { id: "calendar", group: "Inbox, information and calendar", title: "Calendar", body: "Approvals due from you, your tasks' due dates, every meeting you are on (with a Join button for the link), your requests' needed-by dates and information dates, by Month, Week, Day or Agenda (a list). The Show dropdown shows or hides each kind and counts its entries. Add private entries of your own. Profile → Calendar connects Google Calendar (optional).", link: { href: "/users/calendar", label: "Calendar" } },
  { id: "analytics", group: "Inbox, information and calendar", title: "Analytics", body: "Numbers for your requests, your approvals, your tasks (My tasks), your team or your department (as your access allows): approvals, tasks and information, with drill-down lists. Each dashboard comes in pages that fit the screen.", link: { href: "/users/analytics", label: "Analytics" } },
  { id: "ai", group: "Inbox, information and calendar", title: "AI Assistant (Pico Bot)", body: "If IT gave you access (the page has its title, AI Assistant, at the top since v1.89.0): ask in plain words for answers, dashboards and insights from your data. It reads only what you may see and can't approve, send or change anything. Check important figures before relying on them. In a Draft task, ✨ can write the description." },
  { id: "profile", group: "Your account", title: "Profile and photo", body: "Your details from IT, your manager and team, and your access. Add a photo and a few words About me; colleagues see them on your card. Until you add a photo, your picture is the ARS CMS round icon: blue if your designation is an approver one, white otherwise.", link: { href: "/users/profile", label: "Profile" } },
  { id: "push", group: "Your account", title: "Phone and desktop notifications", body: "Profile → App & devices → Turn on notifications on this device, on each phone or computer you use. They come even when the app is closed or you're signed out; choose which kinds under Profile → Notifications → Phone & desktop. On iPhone and iPad they work in the installed app. Remove a device you no longer use.", link: { href: "/users/profile/devices", label: "App & devices" } },
  { id: "session", group: "Your account", title: "How long you stay signed in", body: "On a phone, a tablet or the installed app: until midnight (India time), even if you close the app. On a computer: until a while without activity (IT sets it), and at most 12 hours. Keep your devices locked." },
  { id: "notify", group: "Your account", title: "Notifications (what reaches you)", body: "Profile → Notifications: choose kind by kind what reaches you in the app, by email and on WhatsApp. Approvals waiting for you and security messages always come. Do not disturb pauses them for a while, outside your hours or on days off. The Inbox always has everything.", link: { href: "/users/notifications/settings", label: "Notifications" } },
  { id: "ooo", group: "Your account", title: "Going on leave (out of office)", body: "Name someone to approve for you between two dates (India time). The start can be up to 30 days back to record leave already taken; dates already over are only recorded. They see approvals already waiting and new ones; both names are recorded. You can end it early. Nobody acts on their own request this way.", link: { href: "/users/delegation", label: "Out of office" } },
  { id: "security", group: "Your account", title: "Sign-in & devices", body: "Where and when you signed in, and the devices you use. Sign out of other devices if something looks wrong, and tell IT.", link: { href: "/users/security", label: "Sign-in & devices" } },
  { id: "it", group: "Your account", title: "Something isn't working", body: "Use Copy details for IT below and paste it in your message to IT, with what you were doing. It doesn't include anything private." },
  { id: "s-progress", group: "Statuses", title: "In progress", body: "Waiting for approval at one or more levels." },
  { id: "s-hold", group: "Statuses", title: "On hold", body: "An approver paused it. Nothing moves and the response time stops until it is resumed." },
  { id: "s-changes", group: "Statuses", title: "Changes required", body: "An approver asked the requester to change something. The requester edits and resubmits it; the same checks as a new request apply. If the new details change which levels are needed (for example a higher amount), it starts again from the first level affected; approvals before it stand, and the history says which levels were added or removed." },
  { id: "s-approved", group: "Statuses", title: "Approved", body: "Every required level approved. It is finished." },
  { id: "s-expired", group: "Statuses", title: "Expired", body: "An approved request of a type with a validity period, past its valid-until date. It is still on record as approved, but shown as Expired everywhere. You can amend it or raise a follow-up from it; you'll be asked why, and the reason is kept on its history." },
  { id: "s-rejected", group: "Statuses", title: "Rejected", body: "An approver rejected it. It is finished and never counts as approved." },
  { id: "s-withdrawn", group: "Statuses", title: "Withdrawn", body: "The requester withdrew it before it finished." },
  { id: "t-waiting", group: "Approval steps", title: "Not started / Waiting for approval", body: "A level that hasn't been reached yet, or one waiting for its approvers now." },
  { id: "t-skipped", group: "Approval steps", title: "Skipped / Not needed", body: "A level the rules left out for this request (for example below an amount), or one that wasn't needed once others decided. A request is never approved without at least one real approval: if every level is skipped, it goes to the requester's head of department (or IT, if there is none) to approve, unless IT set the type to allow it. In parallel levels where any one (or any N) is enough, IT can let the other branches carry on when one branch rejects." },
  { id: "t-blocked", group: "Approval steps", title: "Blocked", body: "Nobody could be found for a level (for example no HOD set). IT is told and chooses who decides; nobody can move a step of their own request on." },
  { id: "t-overdue", group: "Approval steps", title: "Due soon / Overdue", body: "A level can have a response time in working hours. You get a heads-up when it is nearly due, a reminder when it is overdue, and then the manager is told." },
];

